// Poulpy's drawings, by file name, from design/poulpy (generated by design/build-poulpy.mjs).
const files = import.meta.glob<string>('../../../design/poulpy/*.svg', { eager: true, query: '?url', import: 'default' })

export const poulpyDrawings = Object.fromEntries(
  Object.entries(files).map(([path, url]) => [path.slice(path.lastIndexOf('/') + 1, -'.svg'.length), url]),
) as Record<PoulpyDrawing, string>

export type PoulpyDrawing =
  | 'mood_proud' | 'mood_happy' | 'mood_recovering' | 'mood_annoyed' | 'mood_grumpy' | 'mood_fuming'
  | 'pose_champion' | 'pose_cocky' | 'pose_exhausted' | 'pose_fuming' | 'pose_patched_up' | 'pose_pouting'
  | 'pose_shy' | 'pose_side_glance' | 'pose_sleeping' | 'pose_standing_tall' | 'pose_straining' | 'pose_thinking'
  | 'loader' | 'loader_small'
